"""Build results/hybrid/HYBRID.md (step 2: PWA model + GCS hybrid MPC) from saved runs."""
import json
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
R = ROOT / "results"


def main():
  L = ["# Step 2: piecewise-affine model and hybrid MPC with Graphs of Convex Sets", "",
       "Generated by `scripts/summarize_hybrid.py` from saved runs.", ""]
  fit = json.load(open(R / "pwa" / "pwa_fit.json"))
  L += ["## 2a. PWA model fit (held-out sysID segments 15300-15399)", "",
        "RMSE in m/s^2 against the network's expected lataccel. One-step from the true past; 20-step free run "
        "with the model's own output fed back, vs the network's expected-value free run on the same inputs. "
        f"Noise floor (network mean vs the sampled lataccel, one step): {fit['_noise_floor_one_step']:.4f}.", "",
        "| model | PID+FF regime one-step | PID+FF regime free-run | MPC regime one-step | MPC regime free-run | first splits |",
        "|---|---:|---:|---:|---:|---|"]
  for name, row in fit.items():
    if name.startswith("_"):
      continue
    a, b = row["PID+FF regime"], row["MPC regime"]
    splits = ", ".join(f"{s['feature']}<{s['threshold']:.2f}" for s in row["splits"][:3])
    L.append(f"| {name} | {a['one_step_rmse']:.4f} | {a['free_run_rmse']:.4f} | {b['one_step_rmse']:.4f} | "
             f"{b['free_run_rmse']:.4f} | {splits} |")
  cc = json.load(open(R / "hybrid" / "crosscheck.json"))
  L += ["", "## 2b. GCS relaxation and rounding vs the exact mixed-integer optimum", "",
        f"{cc['n_instances']} hybrid MPC problems from closed-loop runs on dev segments 10000-10007 (every 20th step), "
        f"8 regions, horizon {cc['H']}. Exact optimum: convex-hull MIQP solved by SCIP (all {cc['n_with_optimum']} "
        "proved optimal), its cost evaluated by a fixed-mode QP.", "",
        f"- Relaxation (lower bound) below the optimum: median {100 * cc['relaxation_below_optimum_median']:.1f}%, "
        f"mean {100 * cc['relaxation_below_optimum_mean']:.1f}%.",
        f"- Rounded GCS solution above the optimum: median {100 * cc['rounded_above_optimum_median']:.1f}%, "
        f"mean {100 * cc['rounded_above_optimum_mean']:.1f}%; within 1% on {100 * cc['rounded_within_1pct']:.1f}% of problems.",
        f"- Same first mode as the optimum on {100 * cc['same_first_mode']:.1f}%; mean |difference in applied steer| "
        f"{cc['mean_abs_u0_diff']:.4f}.",
        f"- Mean time (under load): GCS {cc['t_gcs_mean_s']:.1f} s, MIQP {cc['t_miqp_mean_s']:.1f} s."]
  rows = [r for r in cc["rows"] if r["miqp_optimal"] is not None]
  from collections import Counter
  L.append(f"- Rounding candidate that won: {dict(Counter(r['rounding'] for r in rows))}.")
  # closed loop
  L += ["", "## 2c. Closed loop on dev segments 10000-10031", "",
        "| controller | mean total | median total | worst segment | failed solves | median relax gap |",
        "|---|---:|---:|---:|---:|---:|"]
  def row(label, csv, summary=None):
    d = pd.read_csv(R / csv)
    s = json.load(open(R / summary)) if summary else {}
    worst = d.loc[d.total_cost.idxmax()]
    gap = f"{100 * s['rel_gap_median']:.1f}%" if s else ""
    L.append(f"| {label} | {d.total_cost.mean():.2f} | {d.total_cost.median():.2f} | "
             f"{worst.total_cost:.1f} ({int(worst.seg):05d}) | {s.get('n_failed', '')} | {gap} |")
  row("linear MPC (ARX, observer), H = 40", "hybrid/linear_mpc_H40_10000-10031.csv")
  row("linear MPC, H = 8", "hybrid/linear_mpc_H8_10000-10031.csv")
  row("hybrid-MPC code + the linear MPC's ARX (check)", "hybrid/hybrid_code_mpc_arx_10000-10031.csv",
      "hybrid/hybrid_code_mpc_arx_10000-10031_summary.json")
  row("hybrid-MPC code + speed-binned refit", "hybrid/hybrid_gcs_speedbins_10000-10031.csv",
      "hybrid/hybrid_gcs_speedbins_10000-10031_summary.json")
  row("hybrid MPC + 8-region PWA (GCS)", "hybrid/hybrid_gcs_pwa8_10000-10031.csv",
      "hybrid/hybrid_gcs_pwa8_10000-10031_summary.json")
  il = pd.read_csv(R / "runs" / "ilqr_10000-10499.csv").iloc[:32]
  L.append(f"| final iLQR (same segments) | {il.total_cost.mean():.2f} | {il.total_cost.median():.2f} | "
           f"{il.total_cost.max():.1f} | | |")
  h = pd.read_csv(R / "hybrid" / "hybrid_gcs_pwa8_10000-10031.csv").set_index("seg")
  l8 = pd.read_csv(R / "hybrid" / "linear_mpc_H8_10000-10031.csv").set_index("seg")
  d = h.total_cost - l8.total_cost
  L += ["", f"Hybrid PWA vs linear MPC (H = 8), per segment: median difference {d.median():+.2f}; hybrid worse on "
        f"{(d > 0).sum()} of {len(d)} segments; differences above 40 on {(d > 40).sum()} segments."]
  diag = json.load(open(R / "hybrid" / "diag_seg10009.json"))
  th = [s["threshold"] for s in fit["PWA tree on (y_prev, u) only, 8 regions"]["splits"] if s["feature"] == "u"]
  u = np.array(diag["u"])[100:500]
  on = int((np.min(np.abs(u[:, None] - np.array(th)[None]), 1) < 1e-3).sum())
  L += ["", "### Why the hybrid MPC blows up (segment 10009, `scripts/diagnose_hybrid.py`)", "",
        f"No solve failed on that segment (failed steps: {diag['failed_steps']}). From step {diag['first_err_gt_1']} the "
        f"lataccel error exceeds 1 m/s^2 and stays there while the steer is parked on a region boundary: {on} of the "
        f"400 scored steps have the steer within 0.001 of one of the tree's steer thresholds "
        f"({', '.join(f'{x:.3f}' for x in th)}). Our reading: the PWA model is discontinuous at its boundaries, the two "
        "neighbouring affine models disagree there, and the optimizer settles on a boundary point whose predicted "
        "response the real system does not deliver. A continuous PWA model (continuity constraints at the boundaries, "
        "or hinging hyperplanes) would test this; we did not build one."]
  t = json.load(open(R / "timing.json")).get("hybrid_gcs")
  if t:
    L += ["", f"Single-thread time per step (idle machine, {t['n_steps']} steps): mean {t['ms_per_step']:.0f} ms, max "
          f"{t['ms_max']:.0f} ms, against a 100 ms control period. Not real-time. A test run on 5000 segments was not done: "
          "at this speed it would take roughly 400 CPU-hours, and the method is not competitive on dev."]
  (R / "hybrid" / "HYBRID.md").write_text("\n".join(L) + "\n")
  print("\n".join(L))


if __name__ == "__main__":
  main()
